485	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
486	    @Override
487	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
488	        Owner owner = this.clinicService.findOwnerById(ownerId);
489	        if (owner == null) {
490	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
491	        }
492	        HttpHeaders headers = new HttpHeaders();
493	        Pet pet = petMapper.toPet(petFieldsDto);
494	        owner.setId(ownerId);
495	        pet.setOwner(owner);
496	        pet.getType().setName(null);
497	        this.clinicService.savePet(pet);
498	        PetDto petDto = petMapper.toPetDto(pet);
499	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
500	            .buildAndExpand(pet.getId()).toUri());
501	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
502	    }
