504	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
505	    @Override
506	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
507	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
508	        if (currentOwner != null) {
509	            Pet currentPet = this.clinicService.findPetById(petId);
510	            if (currentPet != null) {
511	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
512	                currentPet.setName(petFieldsDto.getName());
513	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
514	                this.clinicService.savePet(currentPet);
515	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
516	            }
517	        }
518	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
519	    }
