537	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
538	    @Override
539	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
540	        Owner owner = this.clinicService.findOwnerById(ownerId);
541	        if (owner != null) {
542	            Pet pet = owner.getPet(petId);
543	            if (pet != null) {
544	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
545	            }
546	        }
547	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
548	    }
